// Execute the entire sealed suite with only out-of-window CPU counters added.
import { spawn } from 'node:child_process';
import { registerHooks } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const [binary, configFile, output] = process.argv.slice(2);
const config = JSON.parse(readFileSync(configFile));
const rows=[];
let entry, current;
function stat() {
 const line=readFileSync(`/proc/${entry.pid}/stat`,'utf8');
 const f=line.slice(line.lastIndexOf(')')+2).trim().split(/\s+/);
 return {user:Number(f[11])*10,system:Number(f[12])*10,threads:Number(f[17])};
}
globalThis.__forgeMark=(event,name,round,ms)=>{
 if(event==='start'){current=stat();current.client=process.cpuUsage();}
 else {
  const cpu=process.cpuUsage(current.client);
  const after=stat();
  rows.push({workload:name,round:round+1,wall_ms:ms,forge_cpu_ms:after.user+after.system-current.user-current.system,
   client_cpu_ms:(cpu.user+cpu.system)/1000,client_user_ms:cpu.user/1000,client_system_ms:cpu.system/1000,forge_user_ms:after.user-current.user,forge_system_ms:after.system-current.system,threads:after.threads});
 }
};
const sealed='file:///kit/program/env/server.mjs';
const hooks=registerHooks({load(url,context,next){
 const result=next(url,context);if(url!==sealed)return result;
 let source=typeof result.source==='string'?result.source:Buffer.from(result.source).toString();
 let starts=0,ends=0;
 source=source.replace(/    const startedAt = run\.now\(\);/g,match=>{starts++;return `    globalThis.__forgeMark('start', run.spec.name, round);\n${match}`;});
 source=source.replace(/    run\.roundsMs\.push\(elapsed\);/g,match=>{ends++;return `    globalThis.__forgeMark('end', run.spec.name, round, elapsed);\n${match}`;});
 const tail=/var code = await main\(\);\nprocess\.exit\(code\);\s*$/;
 if(starts!==4||ends!==4||!tail.test(source))throw new Error('Unknown sealed env layout');
 return{...result,source:source.replace(tail,'export { startEnv };\n')};
}});
let startEnv;
try{({startEnv}=await import(sealed));}finally{hooks.deregister();}
const env=await startEnv({stateDir:'/tmp/state',host:'0.0.0.0',port:8080,env:{MAKEFUN_SHOP_TOKEN:process.env.MAKEFUN_SHOP_TOKEN},log:line=>process.stderr.write(line+'\n')});
entry=spawn(binary,[],{stdio:['ignore','inherit','inherit'],env:{...process.env,...config.env,FORGE_MEASURE_RUNTIME:'0',MAKEFUN_ENV_URL:'http://127.0.0.1:8080'}});
const entryExit=new Promise((resolve,reject)=>{entry.once('error',reject);entry.once('exit',resolve);});
try {
 const outcome=await env.done;
 const result={config,passed:outcome.passed,total:outcome.total,mcp:outcome.state.counts.byGroup.mcp,
  perf:outcome.perf,phase_ms:outcome.phaseMs,rows,state_sha256:createHash('sha256').update(readFileSync('/tmp/state/export/state.json')).digest('hex'),
  versions:process.versions,constrained_memory:process.constrainedMemory(),client_max_rss_kib:process.resourceUsage().maxRSS,binary_sha256:createHash('sha256').update(readFileSync(binary)).digest('hex')};
 writeFileSync(output,JSON.stringify(result,null,2)+'\n');
 console.log('FULL_RESULT '+JSON.stringify(result));
 if(outcome.passed!==120||result.state_sha256!=='a0e98d49854b961230227867235c8615858e006db3763f341ac6154af1445590')process.exitCode=1;
 if(await entryExit!==0)throw new Error('Native entry failed');
}finally{if(entry.exitCode===null)entry.kill();await env.stop();}

