+func (s *ownerServer) closeDescriptors() {
+	for _, fd := range []*int{&s.listener, &s.epfd, &s.wakeRead} {
+		if *fd >= 0 {
+			s.closeFD(*fd)
+			*fd = -1
+		}
+	}
+	s.wakeMu.Lock()
+	if s.wakeWrite >= 0 {
+		s.closeFD(s.wakeWrite)
+		s.wakeWrite = -1
+	}
+	s.wakeMu.Unlock()
+}
