+func (s *ownerServer) signalStop() {
+	s.wakeMu.Lock()
+	defer s.wakeMu.Unlock()
+	if s.wakeWrite < 0 {
+		return
+	}
+	n, e := rawSendFD(s.wakeWrite, []byte{1})
