+	// wakeup, closing this end makes the watched peer readable at EOF/HUP.
+	if (e != 0 && e != syscall.EAGAIN) || (e == 0 && n != 1) {
+		s.closeFD(s.wakeWrite)
+		s.wakeWrite = -1
+	}
